# Public API (cm:*)
  @api cm:setContext(newTake)  @ 425-430
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 423
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 424
  @api cm:clearTake()  @ 432-437
  @api cm:boundTake()  @ 440
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 439
  @api cm:boundTrack()  @ 443
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 442
  @api cm:setTrack(newTrack)  @ 445-450
  @api cm:pollUndo()  @ 453
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 452
  @api cm:isDeclared(key)  @ 490
      @contract  non-raising existence test against the schema; true iff key is declared  @ 489
  @api cm:get(key, opts)  @ 497-504
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 507-516
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 506
  @api cm:valueFor(handle, scope, key)  @ 519-526
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 518
  @api cm:defaultFor(key)  @ 529-532
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 528
  -- Writing
  @api cm:set(level, key, value)  @ 537-547
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 536
  @api cm:remove(level, key)  @ 550-561
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 549
  @api cm:assign(level, updates)  @ 564-578
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 563

